    bg = max(freq, key=freq.get)
    divider = next(r for r, row in enumerate(g)
                   if len(set(row)) == 1 and row[0] != bg)

    # Mark the row immediately above the non-background object.
    object_rows = [
        r for r in range(divider)
        if any(v != bg for v in g[r])
    ]
    if object_rows:
        g[min(object_rows) - 1] = [8] * w
    return g
